insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('1ki-8-15','1ki','열왕기상',8,15,'왕이 이르되 이스라엘의 하나님 여호와를 송축할지로다 여호와께서 그의 입으로 내 아버지 다윗에게 말씀하신 것을 이제 그의 손으로 이루셨도다 이르시기를',9001),
('1ki-8-16','1ki','열왕기상',8,16,'내가 내 백성 이스라엘을 애굽에서 인도하여 낸 날부터 내 이름을 둘 만한 집을 건축하기 위하여 이스라엘 모든 지파 가운데에서 아무 성읍도 택하지 아니하고 다만 다윗을 택하여 내 백성 이스라엘을 다스리게 하였노라 하신지라',9002),
('1ki-8-17','1ki','열왕기상',8,17,'내 아버지 다윗이 이스라엘의 하나님 여호와의 이름을 위하여 성전을 건축할 마음이 있었더니',9003),
('1ki-8-18','1ki','열왕기상',8,18,'여호와께서 내 아버지 다윗에게 이르시되 네가 내 이름을 위하여 성전을 건축할 마음이 있으니 이 마음이 네게 있는 것이 좋도다',9004),
('1ki-8-19','1ki','열왕기상',8,19,'그러나 너는 그 성전을 건축하지 못할 것이요 네 몸에서 낳을 네 아들 그가 내 이름을 위하여 성전을 건축하리라 하시더니',9005),
('1ki-8-20','1ki','열왕기상',8,20,'이제 여호와께서 말씀하신 대로 이루시도다 내가 여호와께서 말씀하신 대로 내 아버지 다윗을 이어서 일어나 이스라엘의 왕위에 앉고 이스라엘의 하나님 여호와의 이름을 위하여 성전을 건축하고',9006),
('1ki-8-21','1ki','열왕기상',8,21,'내가 또 그 곳에 우리 조상들을 애굽 땅에서 인도하여 내실 때에 그들과 세우신 바 여호와의 언약을 넣은 궤를 위하여 한 처소를 설치하였노라',9007),
('1ki-8-22','1ki','열왕기상',8,22,'솔로몬이 여호와의 제단 앞에서 이스라엘의 온 회중과 마주서서 하늘을 향하여 손을 펴고',9008),
('1ki-8-23','1ki','열왕기상',8,23,'이르되 이스라엘의 하나님 여호와여 위로 하늘과 아래로 땅에 주와 같은 신이 없나이다 주께서는 온 마음으로 주의 앞에서 행하는 종들에게 언약을 지키시고 은혜를 베푸시나이다',9009),
('1ki-8-24','1ki','열왕기상',8,24,'주께서 주의 종 내 아버지 다윗에게 하신 말씀을 지키사 주의 입으로 말씀하신 것을 손으로 이루심이 오늘과 같으니이다',9010),
('1ki-8-25','1ki','열왕기상',8,25,'이스라엘의 하나님 여호와여 주께서 주의 종 내 아버지 다윗에게 말씀하시기를 네 자손이 자기 길을 삼가서 네가 내 앞에서 행한 것 같이 내 앞에서 행하기만 하면 네게서 나서 이스라엘의 왕위에 앉을 사람이 내 앞에서 끊어지지 아니하리라 하셨사오니 이제 다윗을 위하여 그 하신 말씀을 지키시옵소서',9011),
('1ki-8-26','1ki','열왕기상',8,26,'그런즉 이스라엘의 하나님이여 원하건대 주는 주의 종 내 아버지 다윗에게 하신 말씀이 확실하게 하옵소서',9012),
('1ki-8-27','1ki','열왕기상',8,27,'하나님이 참으로 땅에 거하시리이까 하늘과 하늘들의 하늘이라도 주를 용납하지 못하겠거든 하물며 내가 건축한 이 성전이오리이까',9013),
('1ki-8-28','1ki','열왕기상',8,28,'그러나 내 하나님 여호와여 주의 종의 기도와 간구를 돌아보시며 이 종이 오늘 주 앞에서 부르짖음과 비는 기도를 들으시옵소서',9014),
('1ki-8-29','1ki','열왕기상',8,29,'주께서 전에 말씀하시기를 내 이름이 거기 있으리라 하신 곳 이 성전을 향하여 주의 눈이 주야로 보시오며 주의 종이 이 곳을 향하여 비는 기도를 들으시옵소서',9015),
('1ki-8-30','1ki','열왕기상',8,30,'주의 종과 주의 백성 이스라엘이 이 곳을 향하여 기도할 때에 주는 그 간구함을 들으시되 주께서 계신 곳 하늘에서 들으시고 들으시사 사하여 주옵소서',9016),
('1ki-8-31','1ki','열왕기상',8,31,'만일 어떤 사람이 그 이웃에게 범죄함으로 맹세시킴을 받고 그가 와서 이 성전에 있는 주의 제단 앞에서 맹세하거든',9017),
('1ki-8-32','1ki','열왕기상',8,32,'주는 하늘에서 들으시고 행하시되 주의 종들을 심판하사 악한 자의 죄를 정하여 그 행위대로 그 머리에 돌리시고 공의로운 자를 의롭다 하사 그의 의로운 바대로 갚으시옵소서',9018),
('1ki-8-33','1ki','열왕기상',8,33,'만일 주의 백성 이스라엘이 주께 범죄하여 적국 앞에 패하게 되므로 주께로 돌아와서 주의 이름을 인정하고 이 성전에서 주께 기도하며 간구하거든',9019),
('1ki-8-34','1ki','열왕기상',8,34,'주는 하늘에서 들으시고 주의 백성 이스라엘의 죄를 사하시고 그들의 조상들에게 주신 땅으로 돌아오게 하옵소서',9020),
('1ki-8-35','1ki','열왕기상',8,35,'만일 그들이 주께 범죄함으로 말미암아 하늘이 닫히고 비가 없어서 주께 벌을 받을 때에 이 곳을 향하여 기도하며 주의 이름을 찬양하고 그들의 죄에서 떠나거든',9021),
('1ki-8-36','1ki','열왕기상',8,36,'주는 하늘에서 들으사 주의 종들과 주의 백성 이스라엘의 죄를 사하시고 그들이 마땅히 행할 선한 길을 가르쳐 주시오며 주의 백성에게 기업으로 주신 주의 땅에 비를 내리시옵소서',9022),
('1ki-8-37','1ki','열왕기상',8,37,'만일 이 땅에 기근이나 전염병이 있거나 곡식이 시들거나 깜부기가 나거나 메뚜기나 황충이 나거나 적국이 와서 성읍을 에워싸거나 무슨 재앙이나 무슨 질병이 있든지 막론하고',9023),
('1ki-8-38','1ki','열왕기상',8,38,'한 사람이나 혹 주의 온 백성 이스라엘이 다 각각 자기의 마음에 재앙을 깨닫고 이 성전을 향하여 손을 펴고 무슨 기도나 무슨 간구를 하거든',9024),
('1ki-8-39','1ki','열왕기상',8,39,'주는 계신 곳 하늘에서 들으시고 사하시며 각 사람의 마음을 아시오니 그들의 모든 행위대로 행하사 갚으시옵소서 주만 홀로 사람의 마음을 다 아심이니이다',9025),
('1ki-8-40','1ki','열왕기상',8,40,'그리하시면 그들이 주께서 우리 조상들에게 주신 땅에서 사는 동안에 항상 주를 경외하리이다',9026),
('1ki-8-41','1ki','열왕기상',8,41,'또 주의 백성 이스라엘에 속하지 아니한 자 곧 주의 이름을 위하여 먼 지방에서 온 이방인이라도',9027),
('1ki-8-42','1ki','열왕기상',8,42,'그들이 주의 크신 이름과 주의 능한 손과 주의 펴신 팔의 소문을 듣고 와서 이 성전을 향하여 기도하거든',9028),
('1ki-8-43','1ki','열왕기상',8,43,'주는 계신 곳 하늘에서 들으시고 이방인이 주께 부르짖는 대로 이루사 땅의 만민이 주의 이름을 알고 주의 백성 이스라엘처럼 경외하게 하시오며 또 내가 건축한 이 성전을 주의 이름으로 일컫는 줄을 알게 하옵소서',9029),
('1ki-8-44','1ki','열왕기상',8,44,'주의 백성이 그들의 적국과 더불어 싸우고자 하여 주께서 보내신 길로 나갈 때에 그들이 주께서 택하신 성읍과 내가 주의 이름을 위하여 건축한 성전이 있는 쪽을 향하여 여호와께 기도하거든',9030),
('1ki-8-45','1ki','열왕기상',8,45,'주는 하늘에서 그들의 기도와 간구를 들으시고 그들의 일을 돌아보옵소서',9031),
('1ki-8-46','1ki','열왕기상',8,46,'범죄하지 아니하는 사람이 없사오니 그들이 주께 범죄함으로 주께서 그들에게 진노하사 그들을 적국에게 넘기시매 적국이 그들을 사로잡아 원근을 막론하고 적국의 땅으로 끌어간 후에',9032),
('1ki-8-47','1ki','열왕기상',8,47,'그들이 사로잡혀 간 땅에서 스스로 깨닫고 그 사로잡은 자의 땅에서 돌이켜 주께 간구하기를 우리가 범죄하여 반역을 행하며 악을 지었나이다 하며',9033),
('1ki-8-48','1ki','열왕기상',8,48,'자기를 사로잡아 간 적국의 땅에서 온 마음과 온 뜻으로 주께 돌아와서 주께서 그들의 조상들에게 주신 땅 곧 주께서 택하신 성읍과 내가 주의 이름을 위하여 건축한 성전 있는 쪽을 향하여 주께 기도하거든',9034),
('1ki-8-49','1ki','열왕기상',8,49,'주는 계신 곳 하늘에서 그들의 기도와 간구를 들으시고 그들의 일을 돌아보시오며',9035),
('1ki-8-50','1ki','열왕기상',8,50,'주께 범죄한 백성을 용서하시며 주께 범한 그 모든 허물을 사하시고 그들을 사로잡아 간 자 앞에서 그들로 불쌍히 여김을 얻게 하사 그 사람들로 그들을 불쌍히 여기게 하옵소서',9036),
('1ki-8-51','1ki','열왕기상',8,51,'그들은 주께서 철 풀무 같은 애굽에서 인도하여 내신 주의 백성, 주의 소유가 됨이니이다',9037),
('1ki-8-52','1ki','열왕기상',8,52,'원하건대 주는 눈을 들어 종의 간구함과 주의 백성 이스라엘의 간구함을 보시고 주께 부르짖는 대로 들으시옵소서',9038),
('1ki-8-53','1ki','열왕기상',8,53,'주 여호와여 주께서 우리 조상을 애굽에서 인도하여 내실 때에 주의 종 모세를 통하여 말씀하심 같이 주께서 세상 만민 가운데에서 그들을 구별하여 주의 기업으로 삼으셨나이다',9039),
('1ki-8-54','1ki','열왕기상',8,54,'솔로몬이 무릎을 꿇고 손을 펴서 하늘을 향하여 이 기도와 간구로 여호와께 아뢰기를 마치고 여호와의 제단 앞에서 일어나',9040),
('1ki-8-55','1ki','열왕기상',8,55,'서서 큰 소리로 이스라엘의 온 회중을 위하여 축복하며 이르되',9041),
('1ki-8-56','1ki','열왕기상',8,56,'여호와를 찬송할지로다 그가 말씀하신 대로 그의 백성 이스라엘에게 태평을 주셨으니 그 종 모세를 통하여 무릇 말씀하신 그 모든 좋은 약속이 하나도 이루어지지 아니함이 없도다',9042),
('1ki-8-57','1ki','열왕기상',8,57,'우리 하나님 여호와께서 우리 조상들과 함께 계시던 것 같이 우리와 함께 계시옵고 우리를 떠나지 마시오며 버리지 마시옵고',9043),
('1ki-8-58','1ki','열왕기상',8,58,'우리의 마음을 주께로 향하여 그의 모든 길로 행하게 하시오며 우리 조상들에게 명령하신 계명과 법도와 율례를 지키게 하시기를 원하오며',9044),
('1ki-8-59','1ki','열왕기상',8,59,'여호와 앞에서 내가 간구한 이 말씀이 주야로 우리 하나님 여호와께 가까이 있게 하시옵고 또 주의 종의 일과 주의 백성 이스라엘의 일을 날마다 필요한 대로 돌아보사',9045),
('1ki-8-60','1ki','열왕기상',8,60,'이에 세상 만민에게 여호와께서만 하나님이시고 그 외에는 없는 줄을 알게 하시기를 원하노라',9046),
('1ki-8-61','1ki','열왕기상',8,61,'그런즉 너희의 마음을 우리 하나님 여호와께 온전히 바쳐 완전하게 하여 오늘과 같이 그의 법도를 행하며 그의 계명을 지킬지어다',9047),
('1ki-8-62','1ki','열왕기상',8,62,'이에 왕과 및 왕과 함께 한 이스라엘이 다 여호와 앞에 희생제물을 드리니라',9048),
('1ki-8-63','1ki','열왕기상',8,63,'솔로몬이 화목제의 희생제물을 드렸으니 곧 여호와께 드린 소가 이만 이천 마리요 양이 십이만 마리라 이와 같이 왕과 모든 이스라엘 자손이 여호와의 성전의 봉헌식을 행하였는데',9049),
('1ki-8-64','1ki','열왕기상',8,64,'그 날에 왕이 여호와의 성전 앞뜰 가운데를 거룩히 구별하고 거기서 번제와 소제와 감사제물의 기름을 드렸으니 이는 여호와의 앞 놋제단이 작으므로 번제물과 소제물과 화목제의 기름을 다 용납할 수 없음이라',9050),
('1ki-8-65','1ki','열왕기상',8,65,'그 때에 솔로몬이 칠 일과 칠 일 도합 십사 일간을 우리 하나님 여호와 앞에서 절기로 지켰는데 하맛 어귀에서부터 애굽 강까지의 온 이스라엘의 큰 회중이 모여 그와 함께 하였더니',9051),
('1ki-8-66','1ki','열왕기상',8,66,'여덟째 날에 솔로몬이 백성을 돌려보내매 백성이 왕을 위하여 축복하고 자기 장막으로 돌아가는데 여호와께서 그의 종 다윗과 그의 백성 이스라엘에게 베푸신 모든 은혜로 말미암아 기뻐하며 마음에 즐거워하였더라',9052),
('1ki-9-1','1ki','열왕기상',9,1,'솔로몬이 여호와의 성전과 왕궁 건축하기를 마치며 자기가 이루기를 원하던 모든 것을 마친 때에',9053),
('1ki-9-2','1ki','열왕기상',9,2,'여호와께서 전에 기브온에서 나타나심 같이 다시 솔로몬에게 나타나사',9054),
('1ki-9-3','1ki','열왕기상',9,3,'여호와께서 그에게 이르시되 네 기도와 네가 내 앞에서 간구한 바를 내가 들었은즉 나는 네가 건축한 이 성전을 거룩하게 구별하여 내 이름을 영원히 그 곳에 두며 내 눈길과 내 마음이 항상 거기에 있으리니',9055),
('1ki-9-4','1ki','열왕기상',9,4,'네가 만일 네 아버지 다윗이 행함 같이 마음을 온전히 하고 바르게 하여 내 앞에서 행하며 내가 네게 명령한 대로 온갖 일에 순종하여 내 법도와 율례를 지키면',9056),
